import io.netty.bootstrap.ServerBootstrap;
import io.netty.buffer.ByteBufUtil;
import io.netty.channel.Channel;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelInitializer;
import io.netty.channel.EventLoopGroup;
import io.netty.channel.SimpleChannelInboundHandler;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import io.netty.channel.socket.nio.NioServerSocketChannel;
import io.netty.handler.codec.http2.DefaultHttp2Headers;
import io.netty.handler.codec.http2.DefaultHttp2HeadersFrame;
import io.netty.handler.codec.http2.Http2DataFrame;
import io.netty.handler.codec.http2.Http2FrameCodecBuilder;
import io.netty.handler.codec.http2.Http2Headers;
import io.netty.handler.codec.http2.Http2HeadersFrame;
import io.netty.handler.codec.http2.Http2MultiplexHandler;
import io.netty.handler.codec.http2.Http2StreamChannel;
import io.netty.handler.codec.http2.Http2StreamFrame;

import java.util.concurrent.ThreadLocalRandom;

public final class Http2Server {
  static final int PORT = 8080;

  public static void main(String[] args) throws Exception {
    EventLoopGroup group = new NioEventLoopGroup(1);
    try {
      ServerBootstrap b = new ServerBootstrap()
          .group(group)
          .channel(NioServerSocketChannel.class)
          .childHandler(new ChannelInitializer<SocketChannel>() {
            @Override
            protected void initChannel(SocketChannel ch) {
              ch.pipeline().addLast(
                  Http2FrameCodecBuilder.forServer().build(),
                  new Http2MultiplexHandler(new ChannelInitializer<Http2StreamChannel>() {
                    @Override
                    protected void initChannel(Http2StreamChannel ch) {
                      ch.pipeline().addLast(new SimpleHandler());
                    }
                  }));
            }
          });

      Channel ch = b.bind(PORT).sync().channel();
      System.out.println("HTTP/2 server listening on port " + PORT);
      ch.closeFuture().sync();
    } finally {
      group.shutdownGracefully().sync();
    }
  }

  static final class SimpleHandler extends SimpleChannelInboundHandler<Http2StreamFrame> {
    @Override
    protected void channelRead0(ChannelHandlerContext ctx, Http2StreamFrame msg) {
      boolean endStream = (msg instanceof Http2HeadersFrame && ((Http2HeadersFrame) msg).isEndStream())
          || (msg instanceof Http2DataFrame && ((Http2DataFrame) msg).isEndStream());
      if (endStream) {
        byte[] txIdBytes = new byte[64];
        ThreadLocalRandom.current().nextBytes(txIdBytes);
        String txId = ByteBufUtil.hexDump(txIdBytes); // 128-byte string

        Http2Headers headers = new DefaultHttp2Headers()
            .status("200")
            .set("transaction-id0", txId)
            .set("transaction-id1", txId)
            .set("transaction-id2", txId)
            .set("transaction-id3", txId)
            .set("transaction-id4", txId)
            .set("transaction-id5", txId)
            .set("transaction-id6", txId)
            .set("transaction-id7", txId)
            .set("transaction-id8", txId)
            .set("transaction-id9", txId);
        ctx.writeAndFlush(new DefaultHttp2HeadersFrame(headers, true));
      }
    }
  }
}
