package io.netty.handler.codec.haproxy;

import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * F001 - grandchild {@link ByteBuf} refCnt leak on the PROXY-v2 nested-SSL-TLV error path
 * (module codec-haproxy, {@code HAProxyMessage.readNextTLV}).
 *
 * <p>When {@code readNextTLV} parses an SSL TLV it collects its immediate children into a
 * NON-flattened list ({@code encapsulatedTlvs}). If a later sibling is malformed the inner
 * catch releases that list with {@code releaseTlvs}, whose skip-counter assumes a FLATTENED
 * list. A child that is itself an SSL TLV therefore has its grandchildren skipped and never
 * released, leaking the grandchild's retained slice of the shared header buffer.</p>
 *
 * <p>Oracle: after the error-path decode throws, {@code header.refCnt()} is {@code 2}
 * (grandchild slice still retained = leaked) on the vulnerable tree, and {@code 1} (grandchild
 * released) once the inner catch releases recursively.</p>
 */
public class HAProxyTLVGrandchildLeakF001Test {

    /**
     * A minimal (52-byte) PROXY-v2 header whose top-level SSL TLV encapsulates a child SSL TLV
     * (holding one ALPN grandchild) followed by a malformed sibling SSL TLV that forces the
     * error path. Every byte below is load-bearing; see the F001 evidence bundle.
     */
    private static byte[] malformedHeader() {
        return new byte[] {
            // -- 12-byte v2 signature (decodeHeader only skipBytes(12); contents unchecked) --
            0x0D, 0x0A, 0x0D, 0x0A, 0x00, 0x0D, 0x0A, 0x51, 0x55, 0x49, 0x54, 0x0A,
            0x21,             // verCmd: version 2, PROXY command
            0x11,             // protFam: AF_IPv4 + STREAM (TCP4)
            0x00, 0x0C,       // addressInfoLen = 12 (min for IPv4; does not bound the TLV region)
            0x00, 0x00, 0x00, 0x00,  // src addr 0.0.0.0
            0x00, 0x00, 0x00, 0x00,  // dst addr 0.0.0.0
            0x00, 0x00,       // src port
            0x00, 0x00,       // dst port
            // -- outer SSL TLV: type 0x20, len 21 --
            0x20, 0x00, 0x15,
            0x00,                     //   client
            0x00, 0x00, 0x00, 0x00,   //   verify
            // ---- child SSL TLV: type 0x20, len 9 (a grandchild-holder) ----
            0x20, 0x00, 0x09,
            0x00,                     //     client
            0x00, 0x00, 0x00, 0x00,   //     verify
            // ------ ALPN grandchild TLV: type 0x01, len 1 -> readRetainedSlice(1) leaks here
            0x01, 0x00, 0x01,
            (byte) 0xAA,              //       1 sentinel content byte (the leaked slice)
            // ---- malformed sibling SSL TLV: type 0x20, len 1 (< 5) -> throws ----
            0x20, 0x00, 0x01,
            (byte) 0xFF               //     pad so readableBytes() >= 4 at the loop re-entry guard
        };
    }

    /**
     * Proof: the malformed nested header throws, and the grandchild slice must be released so
     * the shared header buffer returns to refCnt 1. On the vulnerable tree it stays at 2.
     */
    @Test
    public void grandchildByteBufIsReleasedOnErrorPath() {
        byte[] wire = malformedHeader();
        final ByteBuf header = Unpooled.buffer().writeBytes(wire);
        assertEquals(1, header.refCnt(), "precondition: freshly allocated buffer");

        assertThrows(HAProxyProtocolException.class, new org.junit.jupiter.api.function.Executable() {
            @Override
            public void execute() {
                HAProxyMessage.decodeHeader(header);
            }
        });

        int refCnt = header.refCnt();
        int leakedBytes = refCnt - 1; // each un-released grandchild slice = one retained sentinel byte
        System.out.println("[F001] crafted wire input = " + wire.length + " bytes");
        if (refCnt == 1) {
            System.out.println("[F001] SAFE: error-path decode released the grandchild; header.refCnt()=1");
        } else {
            System.out.println("[F001] VULNERABLE: grandchild ByteBuf leaked on the readNextTLV error path; "
                    + "header.refCnt()=" + refCnt + " (expected 1), sentinel OOB bytes leaked = " + leakedBytes);
        }

