        assertEquals(1, refCnt,
                "grandchild TLV ByteBuf leaked on the readNextTLV error path (refCnt should be 1)");
        assertTrue(header.release(), "buffer should be fully released");
        assertEquals(0, header.refCnt());
    }

    /**
